      slot: o.slot,
      cell: o.cell,
      tag: S.spec(o).tag,
      q: Math.min(4, Math.ceil(2 * ratio * (0.75 + 0.5 * o.dna.body))),
      E: S.round(0.5 * (o.E + o.B)),
