          if (B <= 0) continue;
          harvest = {consumedB:B,beforeEdibleB:S.edibleB(obj)};
          if(ctx.primaryHooks)harvest.fraction=B/harvest.beforeEdibleB;
          obj.B = S.round(obj.B - B);
          obj.M = S.round(obj.M - M);
